def generateImage(api_key, body, **_extra):
    import json, os, datetime, time, re, secrets, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0327000" if __import__("os").path.isdir("./environment_mix/0327000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started_ts = time.time()
    endpoint = "generateImage"

    def _now_dt():
        return datetime.datetime.utcnow().replace(microsecond=0, tzinfo=datetime.timezone.utc)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_iso_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a date-time string", field=field)
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO-8601 date-time", field=field)

    def _period_start(dt, granularity):
        if granularity == "hour":
            return dt.replace(minute=0, second=0, microsecond=0)
        if granularity == "day":
            return dt.replace(hour=0, minute=0, second=0, microsecond=0)
        if granularity == "month":
            return dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        return None

    def _gen_id(prefix):
        # match style used in store: jmg_*_01 + base32ish. We'll use deterministic-ish hex but with jmg prefix.
        return f"{prefix}_01{secrets.token_hex(11).upper()}"

    def _ensure_request_log(logs, api_key_id, account_id, status_code):
        # Schema did not declare request_logs, but broken code used it; keep observable dynamics if file exists/used.
        # Create file if present or previously created; otherwise no-op.
        if not isinstance(logs, list):
            return None
        latency_ms = int(max(0, (time.time() - started_ts) * 1000))
        row = {
            "id": "req_" + os.urandom(12).hex(),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "account_id": account_id,
            "status": status_code,
            "latency_ms": latency_ms,
            "created_at": _now_iso(),
        }
        logs.append(row)
        return row

    # --------- Validate inputs first ---------
    if not isinstance(api_key, str):
        return _err("VALIDATION_ERROR", "api_key must be a string", field="api_key")
    if not re.match(r"^jmg_[A-Za-z0-9]+_[A-Za-z0-9]+$", api_key):
        return _err("VALIDATION_ERROR", "api_key has invalid format", field="api_key")

    if not isinstance(body, dict):
        return _err("VALIDATION_ERROR", "body must be an object", field="body")
    allowed = {
        "prompt", "negative_prompt", "width", "height", "num_images", "seed", "steps",
        "guidance_scale", "style", "output_format", "callback_url", "metadata"
    }
    for k in body.keys():
        if k not in allowed:
            return _err("VALIDATION_ERROR", f"body contains unknown field '{k}'", field=f"body.{k}")

    if "prompt" not in body or not isinstance(body.get("prompt"), str) or not body["prompt"].strip():
        return _err("VALIDATION_ERROR", "prompt is required and must be a non-empty string", field="body.prompt")

    def _check_int(name, minv=None, maxv=None):
        if name not in body or body[name] is None:
            return None
        v = body[name]
        if not isinstance(v, int):
            raise ValueError(f"{name} must be an integer")
        if minv is not None and v < minv:
            raise ValueError(f"{name} must be >= {minv}")
        if maxv is not None and v > maxv:
            raise ValueError(f"{name} must be <= {maxv}")
        return v

    def _check_num(name, minv=None):
        if name not in body or body[name] is None:
            return None
        v = body[name]
        if not isinstance(v, (int, float)) or isinstance(v, bool):
            raise ValueError(f"{name} must be a number")
        if minv is not None and float(v) < minv:
            raise ValueError(f"{name} must be >= {minv}")
        return float(v)

    try:
        width = _check_int("width", 64, None)
        height = _check_int("height", 64, None)
        num_images = _check_int("num_images", 1, 10)
        steps = _check_int("steps", 1, None)
        seed = _check_int("seed", None, None)
        guidance_scale = _check_num("guidance_scale", 0)
    except ValueError as ve:
        msg = str(ve)
        field = "body." + msg.split(" ")[0]
        return _err("VALIDATION_ERROR", msg, field=field)

    if "output_format" in body and body["output_format"] is not None:
        if body["output_format"] not in ("png", "jpeg", "webp"):
            return _err("VALIDATION_ERROR", "output_format must be one of: png, jpeg, webp", field="body.output_format")
    if "negative_prompt" in body and body["negative_prompt"] is not None and not isinstance(body["negative_prompt"], str):
        return _err("VALIDATION_ERROR", "negative_prompt must be a string", field="body.negative_prompt")
    if "style" in body and body["style"] is not None and not isinstance(body["style"], str):
        return _err("VALIDATION_ERROR", "style must be a string", field="body.style")
    if "callback_url" in body and body["callback_url"] is not None:
        if not isinstance(body["callback_url"], str) or not body["callback_url"].strip():
            return _err("VALIDATION_ERROR", "callback_url must be a non-empty string", field="body.callback_url")
        # light URI check
        if not re.match(r"^https?://", body["callback_url"].strip()):
            return _err("VALIDATION_ERROR", "callback_url must be an http(s) URL", field="body.callback_url")
    if "metadata" in body and body["metadata"] is not None and not isinstance(body["metadata"], dict):
        return _err("VALIDATION_ERROR", "metadata must be an object", field="body.metadata")

    # --------- Load store ---------
    accounts = _load("accounts.json")
    api_keys = _load("api_keys.json")
    jobs = _load("generation_jobs.json")
    images = _load("generated_images.json")
    counters = _load("usage_counters.json")
    req_logs = _load("request_logs.json")
    if not isinstance(req_logs, list):
        req_logs = None  # no-op unless list

    # --------- Authenticate (NEVER by hash; accept id or key_prefix match, or full secret if stored as id) ---------
    # The datastore contains api_keys.id values like jmg_key_...; callers pass api_key looking like jmg_key_...
    # Treat api_key parameter as either:
    #  - exact api_keys.id, OR
    #  - exact api_keys.key_prefix (client-visible prefix), OR
    #  - exact concatenation starting with key_prefix when present (fallback; cannot check secret against hash).
    key_row = None
    if isinstance(api_keys, list):
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            if k.get("id") == api_key or k.get("key_prefix") == api_key:
                key_row = k
                break
        if key_row is None:
            # fallback: match by prefix when api_key starts with stored prefix
            for k in api_keys:
                if not isinstance(k, dict):
                    continue
                if k.get("status") != "active":
                    continue
                kp = k.get("key_prefix")
                if isinstance(kp, str) and kp and isinstance(api_key, str) and api_key.startswith(kp):
                    key_row = k
                    break

    if not key_row:
        if req_logs is not None:
            _ensure_request_log(req_logs, None, None, "UNAUTHORIZED")
            _save("request_logs.json", req_logs)
        return _err("UNAUTHORIZED", "api_key is missing, malformed, revoked, or invalid")

    acc_row = None
    if isinstance(accounts, list):
        for a in accounts:
            if isinstance(a, dict) and a.get("id") == key_row.get("account_id"):
                acc_row = a
                break
    if not acc_row or acc_row.get("status") != "active":
        if req_logs is not None:
            _ensure_request_log(req_logs, key_row.get("id"), key_row.get("account_id"), "UNAUTHORIZED")
            _save("request_logs.json", req_logs)
        return _err("UNAUTHORIZED", "api_key belongs to a non-active account")

    # update last_used_at
    now_iso = _now_iso()
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    # --------- Quota enforcement (daily) ---------
    # Limits are not in schema; choose sensible defaults but enforce.
    # Enforce at account-level aggregate (api_key_id null) and per-key.
    ACCOUNT_DAILY_LIMIT = 500
    KEY_DAILY_LIMIT = 200

    now_dt = _now_dt()
    day_start = _period_start(now_dt, "day")
    day_start_iso = day_start.isoformat().replace("+00:00", "Z")

    def _find_counter(account_id, api_key_id, period_start_iso, gran):
        if not isinstance(counters, list):
            return None
        for c in counters:
            if not isinstance(c, dict):
                continue
            if c.get("account_id") != account_id:
                continue
            if c.get("api_key_id") != api_key_id:
                continue
            if c.get("period_granularity") != gran:
                continue
            if c.get("period_start") == period_start_iso:
                return c
        return None

    def _ensure_counter(account_id, api_key_id, period_start_iso, gran):
        c = _find_counter(account_id, api_key_id, period_start_iso, gran)
        if c:
            return c
        c = {
            "id": _gen_id("jmg_uc"),
            "account_id": account_id,
            "api_key_id": api_key_id,
            "period_start": period_start_iso,
            "period_granularity": gran,
            "jobs_created": 0,
            "images_generated": 0,
            "failed_jobs": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        counters.append(c)
        return c

    acct_counter = _ensure_counter(acc_row["id"], None, day_start_iso, "day")
    key_counter = _ensure_counter(acc_row["id"], key_row["id"], day_start_iso, "day")

    if not isinstance(acct_counter.get("jobs_created"), int) or acct_counter["jobs_created"] < 0:
        acct_counter["jobs_created"] = 0
    if not isinstance(key_counter.get("jobs_created"), int) or key_counter["jobs_created"] < 0:
        key_counter["jobs_created"] = 0

    if acct_counter["jobs_created"] >= ACCOUNT_DAILY_LIMIT:
        if req_logs is not None:
            _ensure_request_log(req_logs, key_row.get("id"), acc_row.get("id"), "QUOTA_EXCEEDED")
            _save("request_logs.json", req_logs)
        return _err("QUOTA_EXCEEDED", "Account daily job quota exceeded", limit=ACCOUNT_DAILY_LIMIT, period_granularity="day", period_start=day_start_iso)

    if key_counter["jobs_created"] >= KEY_DAILY_LIMIT:
        if req_logs is not None:
            _ensure_request_log(req_logs, key_row.get("id"), acc_row.get("id"), "QUOTA_EXCEEDED")
            _save("request_logs.json", req_logs)
        return _err("QUOTA_EXCEEDED", "API key daily job quota exceeded", limit=KEY_DAILY_LIMIT, period_granularity="day", period_start=day_start_iso)

    # --------- Create job (queued) and increment jobs_created atomically with creation ---------
    # Server defaults (versioned)
    defaults_version = "defaults_2026-08-02_r12"
    resolved_input = {
        "prompt": body["prompt"],
        "negative_prompt": body.get("negative_prompt", ""),
        "width": width if width is not None else 1024,
        "height": height if height is not None else 1024,
        "num_images": num_images if num_images is not None else 1,
        "seed": seed if seed is not None else None,
        "steps": steps if steps is not None else 30,
        "guidance_scale": guidance_scale if guidance_scale is not None else 7.0,
        "style": body.get("style", None),
        "output_format": body.get("output_format", "png"),
        "callback_url": body.get("callback_url", None),
        "metadata": body.get("metadata", None),
    }

    job_id = _gen_id("jmg_job")
    job_row = {
        "id": job_id,
        "account_id": acc_row["id"],
        "api_key_id": key_row["id"],
        "status": "queued",
        "provider": "jimeng",
        "input": resolved_input,
        "resolved_defaults_version": defaults_version,
        "attempt": 1,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    if not isinstance(jobs, list):
        jobs = []
    jobs.append(job_row)

    acct_counter["jobs_created"] += 1
    acct_counter["updated_at"] = now_iso
    key_counter["jobs_created"] += 1
    key_counter["updated_at"] = now_iso

    _save("generation_jobs.json", jobs)
    _save("usage_counters.json", counters)

    if req_logs is not None:
        _ensure_request_log(req_logs, key_row.get("id"), acc_row.get("id"), "OK")
        _save("request_logs.json", req_logs)

    # Note: Provider execution is out of scope; job remains queued until another system transitions it.
    return {"job": job_row}

