                "latency_ms": latency_ms,
                "created_at": _now_iso(),
            }
        )

    # Validate
    if not isinstance(api_key, str):
        return _err("VALIDATION_ERROR", "api_key must be a string", field="api_key")
    if not re.match(r"^jmg_[A-Za-z0-9]+_[A-Za-z0-9]+$", api_key):
        return _err("VALIDATION_ERROR", "api_key has invalid format", field="api_key")

    accounts = _load("accounts.json")
