    counters = _load("usage_counters.json")
    req_logs = _load("request_logs.json")
    if not isinstance(req_logs, list):
        req_logs = None

    # Authenticate (id or key_prefix; never hash)
    key_row = None
    if isinstance(api_keys, list):
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            if k.get("id") == api_key or k.get("key_prefix") == api_key:
                key_row = k
                break
        if key_row is None:
            for k in api_keys:
                if not isinstance(k, dict):
                    continue
                if k.get("status") != "active":
                    continue
                kp = k.get("key_prefix")
                if isinstance(kp, str) and kp and api_key.startswith(kp):
                    key_row = k
                    break

    if not key_row:
        if req_logs is not None:
            _ensure_request_log(req_logs, None, None, "UNAUTHORIZED")
