    acc_row = None
    if isinstance(accounts, list):
        for a in accounts:
            if isinstance(a, dict) and a.get("id") == key_row.get("account_id"):
                acc_row = a
                break
    if not acc_row or acc_row.get("status") != "active":
        if req_logs is not None:
            _ensure_request_log(req_logs, key_row.get("id"), key_row.get("account_id"), "UNAUTHORIZED")
            _save("request_logs.json", req_logs)
