    if req_logs is not None:
        _ensure_request_log(req_logs, key_row.get("id"), acc_row.get("id"), "OK")
        _save("request_logs.json", req_logs)

    return resp

def listGenerationJobs(api_key, status=None, created_after=None, created_before=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0327000" if __import__("os").path.isdir("./environment_mix/0327000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started_ts = time.time()
    endpoint = "listGenerationJobs"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_log(logs, api_key_id, account_id, status_code):
        if not isinstance(logs, list):
            return
        latency_ms = int(max(0, (time.time() - started_ts) * 1000))
        logs.append(
            {
                "id": "req_" + os.urandom(12).hex(),
                "endpoint": endpoint,
                "api_key_id": api_key_id,
                "account_id": account_id,
                "status": status_code,
                "latency_ms": latency_ms,
                "created_at": _now_iso(),
            }
        )

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a date-time string", field=field)
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO-8601 date-time", field=field)

    # Validate inputs
    if not isinstance(api_key, str):
        return _err("VALIDATION_ERROR", "api_key must be a string", field="api_key")
    if not re.match(r"^jmg_[A-Za-z0-9]+_[A-Za-z0-9]+$", api_key):
        return _err("VALIDATION_ERROR", "api_key has invalid format", field="api_key")

    if status is not None and status not in ("queued", "running", "succeeded", "failed", "cancelled"):
        return _err("VALIDATION_ERROR", "status must be one of: queued, running, succeeded, failed, cancelled", field="status")

    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200", field="page_size")

    ca, e = _parse_dt(created_after, "created_after")
    if e:
        return e
    cb, e = _parse_dt(created_before, "created_before")
    if e:
        return e

    if page_token is not None and (not isinstance(page_token, str) or not page_token.strip()):
        return _err("VALIDATION_ERROR", "page_token must be a non-empty string when provided", field="page_token")

    accounts = _load("accounts.json")
    api_keys = _load("api_keys.json")
    jobs = _load("generation_jobs.json")
    req_logs = _load("request_logs.json")
    if not isinstance(req_logs, list):
        req_logs = None

    # Authenticate (id or prefix)
    key_row = None
    if isinstance(api_keys, list):
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active" and (k.get("id") == api_key or k.get("key_prefix") == api_key):
                key_row = k
                break
        if key_row is None:
            for k in api_keys:
                if not isinstance(k, dict):
                    continue
                if k.get("status") != "active":
                    continue
                kp = k.get("key_prefix")
                if isinstance(kp, str) and kp and api_key.startswith(kp):
                    key_row = k
                    break
    if not key_row:
        if req_logs is not None:
            _ensure_request_log(req_logs, None, None, "UNAUTHORIZED")
            _save("request_logs.json", req_logs)
        return _err("UNAUTHORIZED", "api_key is invalid or revoked")

    acc_row = None
    if isinstance(accounts, list):
        for a in accounts:
            if isinstance(a, dict) and a.get("id") == key_row.get("account_id"):
                acc_row = a
                break
    if not acc_row or acc_row.get("status") != "active":
        if req_logs is not None:
            _ensure_request_log(req_logs, key_row.get("id"), key_row.get("account_id"), "UNAUTHORIZED")
            _save("request_logs.json", req_logs)
        return _err("UNAUTHORIZED", "account is not active")

    # update last_used_at
    now = _now_iso()
    key_row["last_used_at"] = now
    key_row["updated_at"] = now
    _save("api_keys.json", api_keys)

    # Filter and sort
    if not isinstance(jobs, list):
        jobs = []
    rows = []
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("account_id") != acc_row["id"]:
            continue
        if status is not None and j.get("status") != status:
            continue
        if ca is not None:
            jd, pe = _parse_dt(j.get("created_at"), "created_at")
            if pe:
                continue
            if jd < ca:
                continue
        if cb is not None:
            jd, pe = _parse_dt(j.get("created_at"), "created_at")
            if pe:
                continue
            if jd >= cb:
                continue
        rows.append(j)

    def _dt_key(row):
        s = row.get("created_at")
        try:
            return datetime.datetime.fromisoformat(str(s).replace("Z", "+00:00"))
        except Exception:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    rows.sort(key=_dt_key, reverse=True)

    # Pagination: page_token is last seen job id (opaque enough); start after it
    start_idx = 0
    if page_token:
        for i, r in enumerate(rows):
            if r.get("id") == page_token:
                start_idx = i + 1
                break

    page = rows[start_idx:start_idx + page_size]
    next_cursor = None
    has_more = start_idx + page_size < len(rows)
    if has_more and page:
        next_cursor = page[-1].get("id")

    resp = {
        "jobs": page,
        "meta": {
            "total": len(rows),
            "page_size": page_size,
            "has_more": bool(has_more),
            "next_cursor": next_cursor,
        },
    }

    if req_logs is not None:
        _ensure_request_log(req_logs, key_row.get("id"), acc_row.get("id"), "OK")
        _save("request_logs.json", req_logs)

    return resp

