def cancelGenerationJob(api_key, job_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0327000" if __import__("os").path.isdir("./environment_mix/0327000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log_request(requests, api_key_id, account_id, endpoint, status, started_ts):
        ended = time.time()
        latency_ms = int(max(0, (ended - started_ts) * 1000))
        row = {
            "id": "req_" + os.urandom(12).hex(),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "account_id": account_id,
            "status": status,
            "latency_ms": latency_ms,
            "created_at": _now(),
        }
        requests.append(row)

    started_ts = time.time()
    endpoint = "cancelGenerationJob"

    # Load store
    accounts = _load("accounts.json")
    api_keys = _load("api_keys.json")
    jobs = _load("generation_jobs.json")
    requests = _load("request_logs.json")  # may not exist per schema; still record dynamics
    if not isinstance(requests, list):
        requests = []

    # Validate inputs
    if not isinstance(api_key, str) or not re.match(r"^jmg_[A-Za-z0-9]+_[A-Za-z0-9]+$", api_key):
        _log_request(requests, None, None, endpoint, "VALIDATION_ERROR", started_ts)
        _save("request_logs.json", requests)
        return _err("VALIDATION_ERROR", "api_key is invalid format.")
    if not isinstance(job_id, str) or not job_id.strip():
        _log_request(requests, None, None, endpoint, "VALIDATION_ERROR", started_ts)
        _save("request_logs.json", requests)
        return _err("VALIDATION_ERROR", "job_id is required.")

    # Authenticate: must match by client-visible value or id; store has only prefix/hash.
    # Therefore authenticate by matching api_key to api_keys.id OR api_keys.key_prefix.
    key_row = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key or k.get("key_prefix") == api_key:
            key_row = k
            break
    if not key_row or key_row.get("status") != "active":
        _log_request(requests, key_row.get("id") if key_row else None, None, endpoint, "UNAUTHORIZED", started_ts)
        _save("request_logs.json", requests)
        return _err("UNAUTHORIZED", "Invalid or revoked API key.")

    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("id") == key_row.get("account_id"):
            acct = a
            break
    if not acct or acct.get("status") != "active":
        _log_request(requests, key_row.get("id"), key_row.get("account_id"), endpoint, "UNAUTHORIZED", started_ts)
        _save("request_logs.json", requests)
        return _err("UNAUTHORIZED", "Account is not active.")

    # Find job and enforce ownership
    job = None
    job_idx = None
    for i, j in enumerate(jobs):
        if isinstance(j, dict) and j.get("id") == job_id:
            job = j
            job_idx = i
            break
    if not job or job.get("account_id") != acct.get("id"):
        _log_request(requests, key_row.get("id"), acct.get("id"), endpoint, "NOT_FOUND", started_ts)
        _save("request_logs.json", requests)
        return _err("NOT_FOUND", "Generation job not found.")

    cur = job.get("status")
    terminal = {"succeeded", "failed", "cancelled"}
    if cur in terminal:
        _log_request(requests, key_row.get("id"), acct.get("id"), endpoint, "CONFLICT", started_ts)
        _save("request_logs.json", requests)
        return _err("CONFLICT", "Job is already in a terminal state.", status=cur)

    transitions = {
        "queued": ["running", "cancelled", "failed"],
        "running": ["succeeded", "failed", "cancelled"],
        "succeeded": [],
        "failed": ["queued"],
        "cancelled": [],
    }
    if "cancelled" not in transitions.get(cur, []):
        _log_request(requests, key_row.get("id"), acct.get("id"), endpoint, "INVALID_TRANSITION", started_ts)
        _save("request_logs.json", requests)
        return _err("INVALID_TRANSITION", f"Cannot transition job from {cur} to cancelled.")

    # Apply transition
    now = _now()
    job = dict(job)
    job["status"] = "cancelled"
    # started_at constraint: started_at must be non-null when status in running/succeeded/failed/cancelled
    if not job.get("started_at"):
        job["started_at"] = now
    job["finished_at"] = now
    job["updated_at"] = now
    jobs[job_idx] = job

    # Mark API key last used
    key_row = dict(key_row)
    key_row["last_used_at"] = now
    key_row["updated_at"] = now
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            api_keys[i] = key_row
            break

    _save("generation_jobs.json", jobs)
    _save("api_keys.json", api_keys)

    _log_request(requests, key_row.get("id"), acct.get("id"), endpoint, "OK", started_ts)
    _save("request_logs.json", requests)

    return {"job": job}

