    # Validate inputs
    if not isinstance(api_key, str) or not re.match(r"^jmg_[A-Za-z0-9]+_[A-Za-z0-9]+$", api_key):
        _log_request(requests, None, None, endpoint, "VALIDATION_ERROR", started_ts)
        _save("request_logs.json", requests)
        return _err("VALIDATION_ERROR", "api_key is invalid format.")
    if job_id is not None and (not isinstance(job_id, str) or not job_id.strip()):
        _log_request(requests, None, None, endpoint, "VALIDATION_ERROR", started_ts)
        _save("request_logs.json", requests)
        return _err("VALIDATION_ERROR", "job_id must be a non-empty string when provided.")
    if status is not None and status not in ("available", "deleted"):
        _log_request(requests, None, None, endpoint, "VALIDATION_ERROR", started_ts)
        _save("request_logs.json", requests)
        return _err("VALIDATION_ERROR", "status must be one of: available, deleted.")
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        _log_request(requests, None, None, endpoint, "VALIDATION_ERROR", started_ts)
        _save("request_logs.json", requests)
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200.")

    # Decode page token
    cursor_created_at = None
    cursor_id = None
    if page_token is not None:
        if not isinstance(page_token, str) or not page_token:
            _log_request(requests, None, None, endpoint, "VALIDATION_ERROR", started_ts)
            _save("request_logs.json", requests)
            return _err("VALIDATION_ERROR", "page_token must be a non-empty string when provided.")
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"===")
            tok = json.loads(raw.decode("utf-8"))
            cursor_created_at = tok.get("created_at")
            cursor_id = tok.get("id")
            if not isinstance(cursor_created_at, str) or not isinstance(cursor_id, str):
                raise ValueError("bad token")
            if _parse_dt(cursor_created_at) is None:
                raise ValueError("bad token dt")
        except Exception:
            _log_request(requests, None, None, endpoint, "VALIDATION_ERROR", started_ts)
            _save("request_logs.json", requests)
            return _err("VALIDATION_ERROR", "Invalid page_token.")

    # Authenticate
    key_row = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key or k.get("key_prefix") == api_key:
            key_row = k
            break
    if not key_row or key_row.get("status") != "active":
        _log_request(requests, key_row.get("id") if key_row else None, None, endpoint, "UNAUTHORIZED", started_ts)
        _save("request_logs.json", requests)
        return _err("UNAUTHORIZED", "Invalid or revoked API key.")

    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("id") == key_row.get("account_id"):
            acct = a
            break
    if not acct or acct.get("status") != "active":
        _log_request(requests, key_row.get("id"), key_row.get("account_id"), endpoint, "UNAUTHORIZED", started_ts)
        _save("request_logs.json", requests)
        return _err("UNAUTHORIZED", "Account is not active.")

    # Mark API key last used
    now = _now()
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            nk = dict(k)
            nk["last_used_at"] = now
            nk["updated_at"] = now
            api_keys[i] = nk
            break
    _save("api_keys.json", api_keys)

    # Filter to account + optional filters
    acc_id = acct.get("id")
    filtered = []
    for img in images:
        if not isinstance(img, dict):
            continue
        if img.get("account_id") != acc_id:
            continue
        if job_id is not None and img.get("job_id") != job_id:
            continue
        if status is not None and img.get("status") != status:
            continue
        filtered.append(img)

    # Sort by created_at desc, then id desc for stability
    def _sort_key(r):
        dt = _parse_dt(r.get("created_at")) or datetime.datetime.min
        return (dt, str(r.get("id", "")))

    filtered.sort(key=_sort_key, reverse=True)

    total = len(filtered)

    # Apply cursor pagination (created_at desc)
    if cursor_created_at is not None:
        cdt = _parse_dt(cursor_created_at)
        def _after_cursor(r):
            rdt = _parse_dt(r.get("created_at")) or datetime.datetime.min
            rid = str(r.get("id", ""))
            # since sorted desc, we want items strictly "after" cursor:
            # r comes after cursor if rdt < cdt OR (rdt == cdt and rid < cursor_id) when descending
            if rdt < cdt:
                return True
            if rdt == cdt and rid < cursor_id:
                return True
            return False
        filtered = [r for r in filtered if _after_cursor(r)]

    page = filtered[:page_size]
    has_more = len(filtered) > page_size

    next_cursor = None
    if has_more and page:
        last = page[-1]
        tok = {"created_at": last.get("created_at"), "id": last.get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(tok).encode("utf-8")).decode("utf-8").rstrip("=")

    _log_request(requests, key_row.get("id"), acc_id, endpoint, "OK", started_ts)
    _save("request_logs.json", requests)

    return {
        "images": page,
        "page": {
            "total": total,
            "page_size": page_size,
            "has_more": has_more,
            "next_page_token": next_cursor,
        },
    }

