        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key or k.get("key_prefix") == api_key:
            candidates.append(k)

    # If no candidates, unauthorized
    if not candidates:
        _append_log("UNAUTHORIZED", http_status=401, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "api_key is invalid or not recognized")

    # Prefer a candidate that:
    # 1) is active
    # 2) has an active account
    # 3) (if image exists) belongs to the image's account_id
    best = None
    for k in candidates:
        a = acct_by_id.get(k.get("account_id"))
        if not (_is_active_key(k) and _is_active_account(a)):
            continue
        if img_row is not None:
            # Only accept if it could legitimately access this image
            if img_row.get("account_id") != k.get("account_id"):
                continue
        best = (k, a)
        break

    # If image exists but no active combination can access it, treat as NOT_FOUND (do not leak existence)
    if img_row is not None and best is None:
        _append_log("NOT_FOUND", http_status=404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "generated image not found", image_id=image_id)

    # If image does not exist, still must authenticate with any working active key+account
    if img_row is None:
        for k in candidates:
            a = acct_by_id.get(k.get("account_id"))
            if _is_active_key(k) and _is_active_account(a):
                best = (k, a)
                break
        if best is None:
            _append_log("UNAUTHORIZED", http_status=401, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "api_key is invalid/revoked or account is not active")

        key_row, acct_row = best
        _append_log("NOT_FOUND", api_key_id=key_row.get("id"), account_id=acct_row.get("id"), http_status=404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "generated image not found", image_id=image_id)

    key_row, acct_row = best

    # Enforce "deleted" refusal as NOT_FOUND
    if img_row.get("status") == "deleted":
        _append_log("NOT_FOUND", api_key_id=key_row.get("id"), account_id=acct_row.get("id"), http_status=404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "generated image not found", image_id=image_id)

    # Success response: return the real row with useful storage metadata
    # (Do not fabricate; return exactly stored fields)
    _append_log("OK", api_key_id=key_row.get("id"), account_id=acct_row.get("id"), http_status=200)

    return {
        "image": img_row,
        "account_id": acct_row.get("id"),
        "api_key_id": key_row.get("id"),
    }
